import type { Metadata } from 'next'
import { forbidden, unauthorized } from 'next/navigation'
import { connection } from 'next/server'
import { verifyAdmin } from '@/app/lib/auth'

export const metadata: Metadata = {
  title: 'Admin Dashboard',
}

export default async function AdminPage() {
  // Auth must be evaluated per request, never prerendered at build time.
  await connection()

  const { isAdmin, session } = await verifyAdmin()

  // Not signed in at all -> 401, rendered by app/unauthorized.tsx
  if (!session) {
    unauthorized()
  }

  // Signed in but without the "admin" role -> 403, rendered by app/forbidden.tsx
  if (!isAdmin) {
    forbidden()
  }

  return (
    <main style={{ maxWidth: 720, margin: '4rem auto', padding: '0 1.5rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Dashboard</h1>
      <p>
        Welcome, {session.name}. You are signed in with the <strong>{session.role}</strong> role.
      </p>
    </main>
  )
}
